08. 实战项目 项目 1：客服助手 场景描述 构建一个电商客服助手，能够： - 回答常见问题 - 查询订单状态 - 处理退货请求 - 转接人工客服 完整代码 from langchain.agents import create_agent from typing import Dict import json # 模拟数据库 orders_db = { "ORD001": {"status": "已发货", "date": "2026-03-20"}, "ORD002": {"status": "处理中", "date": "2026-03-22"}, "ORD003": {"status": "已送达", "date": "2026-03-18"}, } # 工具 1：查询订单状态 def check_order_status(order_id: str) -> str: """查询订单状态。 Args: order_id: 订单号（如 ORD001） Returns: 订单状态信息 """ order = orders_db.get(order_id.upper()) if order: return f"订单 {order_id}：{order['status']}，下单日期：{order['date']}" return f"未找到订单 {order_id}" # 工具 2：处理退货 def process_return(order_id: str, reason: str) -> str: """处理退货请求。 Args: order_id: 订单号 reason: 退货原因 Returns: 退货处理结果 """ order = orders_db.get(order_id.upper()) if not order: return f"未找到订单 {order_id}" if order["status"] == "已送达": return f"退货申请已提交，订单：{order_id}，原因：{reason}。客服将在 24 小时内处理。" else: return f"订单 {order_id} 尚未送达，暂不能申请退货。" # 工具 3：查询常见问题 def search_faq(question: str) -> str: """搜索常见问题解答。 Args: question: 问题关键词 Returns: 相关 FAQ 答案 """ faq = { "运费": "满 99 元免运费，否则运费 10 元。", "发货": "工作日 24 小时内发货，周末和节假日顺延。", "退货": "支持 7 天无理由退货，商品需保持完好。", "发票": "确认收货后可在订单详情申请电子发票。", "客服": "客服工作时间：周一至周五 9:00-18:00。", } for key, answer in faq.items(): if key in question: return answer return "抱歉，我没有找到相关信息。您可以联系人工客服。" # 创建 Agent system_prompt = """你是电商客服助手，负责帮助客户解决问题。 你的职责： 1. 回答常见问题（使用 search_faq） 2. 查询订单状态（使用 check_order_status） 3. 处理退货请求（使用 process_return） 4. 无法处理时转接人工客服 服务准则： - 礼貌、专业、耐心 - 先确认客户身份和订单信息 - 提供清晰、准确的答复 - 遇到投诉或复杂问题，建议联系人工客服 可用工具： - search_faq: 回答常见问题 - check_order_status: 查询订单 - process_return: 处理退货 如果客户情绪激动或问题复杂，请说："我理解您的情况，让我为您转接人工客服。" """ agent = create_agent( model="claude-sonnet-4-6", tools=[search_faq, check_order_status, process_return], system_prompt=system_prompt, ) # 运行示例 def run_customer_service(): """运行客服助手""" print("🤖 客服助手已就绪（输入 'exit' 退出）
") messages = [] while True: user_input = input("客户：").strip() if user_input.lower() in ["exit", "quit", "退出"]: print("客服助手：感谢您的咨询，祝您生活愉快！再见！") break messages.append({"role": "user", "content": user_input}) result = agent.invoke({"messages": messages}) assistant_message = result["messages"][-1] messages.append(assistant_message) print(f"客服助手：{assistant_message.content}
") # 测试 if __name__ == "__main__": run_customer_service() 测试用例 # 测试场景 test_scenarios = [ "我的订单 ORD001 怎么样了？", "运费怎么算？", "我要退货，订单 ORD003，商品有质量问题", "什么时候发货？", "投诉！我的订单都延迟一周了！", ] for scenario in test_scenarios: result = agent.invoke({ "messages": [{"role": "user", "content": scenario}] }) print(f"问：{scenario}") print(f"答：{result['messages'][-1].content}
") 项目 2：数据分析助手 场景描述 构建一个数据分析助手，能够： - 执行 SQL 查询 - 生成数据可视化 - 解释分析结果 - 提供业务建议 完整代码 from langchain.agents import create_agent import pandas as pd from datetime import datetime, timedelta # 模拟销售数据 def generate_sales_data(): """生成模拟销售数据""" dates = pd.date_range(end=datetime.now(), periods=30, freq='D') data = { 'date': dates, 'revenue': [10000 + i * 100 + (i % 7) * 500 for i in range(30)], 'orders': [50 + i + (i % 7) * 10 for i in range(30)], 'customers': [30 + i // 2 for i in range(30)], } return pd.DataFrame(data) sales_df = generate_sales_data() # 工具 1：查询销售数据 def query_sales_data( start_date: str = None, end_date: str = None, metric: str = "revenue" ) -> str: """查询销售数据。 Args: start_date: 开始日期（YYYY-MM-DD） end_date: 结束日期（YYYY-MM-DD） metric: 指标（revenue/orders/customers） Returns: 查询结果 """ df = sales_df.copy() if start_date: df = df[df['date'] >= pd.to_datetime(start_date)] if end_date: df = df[df['date'] <= pd.to_datetime(end_date)] if metric not in df.columns: return f"未知指标：{metric}。可用指标：revenue, orders, customers" total = df[metric].sum() avg = df[metric].mean() count = len(df) return f"{metric} 统计（{count}天）：
" \ f" 总计：{total:,.0f}
" \ f" 平均：{avg:,.0f}/天
" \ f" 最高：{df[metric].max():,.0f}
" \ f" 最低：{df[metric].min():,.0f}" # 工具 2：计算增长率 def calculate_growth(metric: str = "revenue", days: int = 7) -> str: """计算增长率。 Args: metric: 指标名称 days: 对比天数 Returns: 增长率信息 """ df = sales_df.copy() if metric not in df.columns: return f"未知指标：{metric}" recent = df.head(days)[metric].sum() previous = df.iloc[days:days*2][metric].sum() growth_rate = ((recent - previous) / previous) * 100 if previous > 0 else 0 trend = "增长" if growth_rate > 0 else "下降" return f"{metric} 趋势（对比前{days}天）：
" \ f" 近期：{recent:,.0f}
" \ f" 前期：{previous:,.0f}
" \ f" 变化：{growth_rate:+.1f}% ({trend})" # 工具 3：生成业务建议 def generate_insights() -> str: """生成业务洞察和建议。 Returns: 业务建议 """ df = sales_df.copy() # 计算关键指标 avg_revenue = df['revenue'].mean() avg_orders = df['orders'].mean() avg_order_value = avg_revenue / avg_orders if avg_orders > 0 else 0 # 周末 vs 工作日 df['day_of_week'] = df['date'].dt.dayofweek weekend_avg = df[df['day_of_week'] >= 5]['revenue'].mean() weekday_avg = df[df['day_of_week'] < 5]['revenue'].mean() insights = [] insights.append("📊 业务洞察报告") insights.append("=" * 40) insights.append(f"• 平均日收入：¥{avg_revenue:,.0f}") insights.append(f"• 平均日订单：{avg_orders:.0f}单") insights.append(f"• 平均客单价：¥{avg_order_value:.0f}") insights.append(f"• 周末日均收入：¥{weekend_avg:,.0f}") insights.append(f"• 工作日均收入：¥{weekday_avg:,.0f}") if weekend_avg > weekday_avg * 1.2: insights.append("
💡 建议：周末表现优异，可增加周末营销投入") elif weekday_avg > weekend_avg * 1.2: insights.append("
💡 建议：工作日表现更好，可推出工作日促销") return "
".join(insights) # 创建 Agent system_prompt = """你是数据分析助手，帮助业务团队分析销售数据。 你的职责： 1. 查询销售数据（使用 query_sales_data） 2. 计算增长趋势（使用 calculate_growth） 3. 提供业务洞察（使用 generate_insights） 4. 用清晰的语言解释数据 分析原则： - 数据驱动，客观准确 - 提供具体的数字支持 - 给出可执行的建议 - 指出异常和趋势 可用工具： - query_sales_data: 查询特定时间段数据 - calculate_growth: 计算增长率 - generate_insights: 生成业务建议 回答时： 1. 先总结关键发现 2. 提供具体数据 3. 给出建议""" agent = create_agent( model="claude-sonnet-4-6", tools=[query_sales_data, calculate_growth, generate_insights], system_prompt=system_prompt, ) # 运行示例 def run_data_analyst(): """运行数据分析助手""" print("🤖 数据分析助手已就绪（输入 'exit' 退出）
