") 项目 3：个人助理 场景描述 构建一个个人助理，能够： - 管理待办事项 - 设置提醒 - 记录笔记 - 回答问题 完整代码 from langchain.agents import create_agent from datetime import datetime, timedelta import json import os TODO_FILE = "todos.json" NOTES_FILE = "notes.json" # 加载数据 def load_data(filename): if os.path.exists(filename): with open(filename, 'r', encoding='utf-8') as f: return json.load(f) return [] # 保存数据 def save_data(filename, data): with open(filename, 'w', encoding='utf-8') as f: json.dump(data, f, ensure_ascii=False, indent=2) # 工具 1：添加待办 def add_todo(task: str, priority: str = "medium", due_date: str = None) -> str: """添加待办事项。 Args: task: 任务描述 priority: 优先级（high/medium/low） due_date: 截止日期（YYYY-MM-DD） Returns: 添加结果 """ todos = load_data(TODO_FILE) todo = { "id": len(todos) + 1, "task": task, "priority": priority, "due_date": due_date, "created_at": datetime.now().strftime("%Y-%m-%d %H:%M"), "completed": False, } todos.append(todo) save_data(TODO_FILE, todos) return f"✅ 已添加待办 #{todo['id']}: {task}" # 工具 2：查看待办 def list_todos(show_completed: bool = False) -> str: """查看待办事项列表。 Args: show_completed: 是否显示已完成的 Returns: 待办列表 """ todos = load_data(TODO_FILE) if not show_completed: todos = [t for t in todos if not t["completed"]] if not todos: return "📝 暂无待办事项" lines = ["📋 待办事项："] for todo in todos: status = "✅" if todo["completed"] else "⬜" priority_icon = {"high": "🔴", "medium": "🟡", "low": "🟢"}.get(todo["priority"], "") lines.append(f"{status} {priority_icon} #{todo['id']}: {todo['task']}") if todo["due_date"]: lines.append(f" 截止：{todo['due_date']}") return "
".join(lines) # 工具 3：完成待办 def complete_todo(todo_id: int) -> str: """标记待办为已完成。 Args: todo_id: 待办 ID Returns: 操作结果 """ todos = load_data(TODO_FILE) for todo in todos: if todo["id"] == todo_id: todo["completed"] = True todo["completed_at"] = datetime.now().strftime("%Y-%m-%d %H:%M") save_data(TODO_FILE, todos) return f"✅ 已完成待办 #{todo_id}: {todo['task']}" return f"❌ 未找到待办 #{todo_id}" # 工具 4：添加笔记 def add_note(title: str, content: str) -> str: """添加笔记。 Args: title: 笔记标题 content: 笔记内容 Returns: 添加结果 """ notes = load_data(NOTES_FILE) note = { "id": len(notes) + 1, "title": title, "content": content, "created_at": datetime.now().strftime("%Y-%m-%d %H:%M"), } notes.append(note) save_data(NOTES_FILE, notes) return f"📝 已添加笔记 #{note['id']}: {title}" # 工具 5：搜索笔记 def search_notes(keyword: str) -> str: """搜索笔记。 Args: keyword: 搜索关键词 Returns: 搜索结果 """ notes = load_data(NOTES_FILE) results = [n for n in notes if keyword.lower() in n["title"].lower() or keyword.lower() in n["content"].lower()] if not results: return f"📝 未找到包含 '{keyword}' 的笔记" lines = [f"🔍 找到 {len(results)} 篇笔记："] for note in results: lines.append(f"
📌 #{note['id']}: {note['title']}") lines.append(f" {note['content'][:100]}...") return "
".join(lines) # 工具 6：获取时间信息 def get_time_info() -> str: """获取当前时间信息。 Returns: 时间信息 """ now = datetime.now() return f"当前时间：{now.strftime('%Y年%m月%d日 %H:%M')}
" \ f"星期：{now.strftime('%A')}" # 创建 Agent system_prompt = """你是个人助理，帮助用户管理日常事务。 你的职责： 1. 管理待办事项（添加、查看、完成） 2. 管理笔记（添加、搜索） 3. 提供时间信息 4. 回答一般问题 工作原则： - 友好、乐于助人 - 主动提醒重要事项 - 帮助用户保持条理 - 记住用户的偏好 可用工具： - add_todo: 添加待办 - list_todos: 查看待办 - complete_todo: 完成待办 - add_note: 添加笔记 - search_notes: 搜索笔记 - get_time_info: 获取时间 主动提醒： - 如果有即将到期的待办，主动提醒 - 如果用户说"谢谢"，礼貌回应""" agent = create_agent( model="claude-sonnet-4-6", tools=[add_todo, list_todos, complete_todo, add_note, search_notes, get_time_info], system_prompt=system_prompt, ) # 运行示例 def run_personal_assistant(): """运行个人助理""" print("🤖 个人助理已就绪（输入 'exit' 退出）
") messages = [] while True: user_input = input("你：").strip() if user_input.lower() in ["exit", "quit", "退出"]: print("助理：祝您有愉快的一天！再见！") break messages.append({"role": "user", "content": user_input}) result = agent.invoke({"messages": messages}) assistant_message = result["messages"][-1] messages.append(assistant_message) print(f"
